        ".ua-order .gallery { position:relative; place-self:stretch; overflow:hidden; }\n.ua-order .gallery img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }\n.ua-order .gallery .gallery-in { animation:ua-gallery-in .25s ease-out; }\n@keyframes ua-gallery-in { from { opacity:.35; } to { opacity:1; } }\n@media (prefers-reduced-motion:reduce) { .ua-order .gallery .gallery-in { animation:none; } }\n.ua-order .gallery > button { position:absolute; top:0; bottom:0; width:50%; min-height:0; margin:0; padding:0; border:0; border-radius:0; background:transparent; }\n.ua-order .gallery > button:focus-visible { outline-offset:-3px; }\n.ua-order .gallery > button::before { content:''; position:absolute; top:50%; width:36px; height:36px; margin-top:-18px; border-radius:50%; background:rgba(11,28,45,.6); transition:background .15s; }\n.ua-order .gallery > button:hover::before { background:rgba(11,28,45,.85); }\n.ua-order .gallery > button::after { content:''; position:absolute; top:50%; width:12px; height:12px; margin-top:-6px; border:solid #ffd23f; border-width:0 3px 3px 0; }\n.ua-order .gallery-prev { left:0; }\n.ua-order .gallery-next { right:0; }\n.ua-order .gallery-prev::before { left:8px; }\n.ua-order .gallery-next::before { right:8px; }\n.ua-order .gallery-prev::after { left:22px; transform:rotate(135deg); }\n.ua-order .gallery-next::after { right:22px; transform:rotate(-45deg); }\n.ua-order .gallery-count { position:absolute; right:8px; bottom:8px; padding:2px 8px; border-radius:10px; background:rgba(11,28,45,.7); color:#f4f5f7; font-size:12px; line-height:1.5; pointer-events:none; }\n.ua-order .model h3 .generation { font-size:14px; font-weight:400; color:#d0dbe3; }\n/* Phones (the site's own 640px breakpoint): the name with its generation on top across the card;\n   below it the larger photo on the left and the card's buttons stacked on the right, one block. */\n@media(max-width:640px) {\n .ua-order .model:has(> .model-media > .gallery) { display:grid; grid-template-columns:minmax(0,3fr) minmax(0,2fr); column-gap:10px; row-gap:8px; padding:12px; }\n .ua-order .model:has(> .model-media > .gallery) > .model-info { display:contents; }\n .ua-order .model:has(> .model-media > .gallery) h3 { grid-row:1; grid-column:1 / -1; }\n .ua-order .model-media:has(> .gallery) { grid-row:2 / span 2; grid-column:1; width:auto; min-height:0; aspect-ratio:4/3; border-radius:8px; }\n .ua-order .model:has(> .model-media > .gallery) .model-info > button { grid-column:2; margin-top:0; padding:6px 8px; font-size:13px; line-height:1.3; }\n .ua-order .model:has(> .model-media > .gallery) .model-info > button:nth-last-of-type(2) { grid-row:2; }\n .ua-order .model:has(> .model-media > .gallery) .model-info > button:last-of-type { grid-row:3; }\n .ua-order .model:has(> .model-media > .gallery) .model-info > button:only-of-type { grid-row:2 / span 2; align-self:end; }\n .ua-order .gallery > button::before { width:30px; height:30px; margin-top:-15px; }\n .ua-order .gallery > button::after { width:10px; height:10px; margin-top:-5px; }\n .ua-order .gallery-prev::before { left:6px; } .ua-order .gallery-next::before { right:6px; }\n .ua-order .gallery-prev::after { left:18px; } .ua-order .gallery-next::after { right:18px; }\n .ua-order .gallery-count { right:6px; bottom:6px; font-size:11px; padding:1px 6px; }\n}\n"
